import org.junit.jupiter.api.Test;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;

public class TextSplitTest {

    @Test
    public void testTextSplitsIntoFour() {
        String text = "Hello World this is an example";
        int[] result1 = text.splitText(4);
        assertThat(result1, is(new int[]{0, 1, 2, 3}));

        int[] result2 = text.splitText(5);
        assertThat(result2, is(new int[]{0, 1, 2, 3, 4}));
    }

    @Test
    public void testTextDoesntSplitIntoFive() {
        String text = "Hello World this is an example";
        int[] result1 = text.splitText(5);
        assertThat(result1, is(new int[]{0, 1, 2, 3, 4}));
    }

    @Test
    public void testEmptyStringReturnsFour() {
        String text = "";
        int[] result = text.splitText(4);
        assertThat(result, is(new int[]{0, 1, 2, 3}));
    }

    @Test
    public void testLongerStringReturnsMultipleParts() {
        String text = "Hello World this is an example with many words";
        int[] result1 = text.splitText(5);
        assertThat(result1, is(new int[]{0, 4, 2, 3, 1}));
    }
}
